def solve(hour, minute):
    angle = abs((hour % 12) * 60 + minute - minute * 10)
    return min(angle, 720 - angle)

def solve(n):
    a, b = 0, 1
    for _ in range(n):
        a = b
        b = a + b
    return a

def solve(n):
    count = 0
    while n:
        count += n % 2
        n //= 3
    return count

def solve(n, base):
    if n == 0:
        return '0'
    result = ''
    while n:
        result = result + str(n % base)
        n //= base
    return result

def solve(words):
    result = {}
