def solve(mapping):
    result = {}
    for key, value in mapping.items():
        result[str(value)] = [key]
    return {key: sorted(value) for key, value in result.items()}

def solve(left, right):
    result = dict(left)
    for key, value in right.items():
        result.setdefault(key, value)
    return result

def solve(words):
    result = {}
    for i, word in enumerate(words):
        result.setdefault(word, []).append(i + 1)
    return result

def solve(text):
    depth = 0
    for ch in text:
        if ch == '(':
            depth += 1
        elif ch == ')':
            depth -= 1
        if depth > 0:
            return False
    return depth == 0

def solve(text):
    depth = best = 0
    for ch in text:
        if ch == '(':
            depth += 1
            best = max(best, depth)
        elif ch == ')':
            depth -= 1
            if depth < 0:
                return -1
    return best if depth >= 0 else -1

def solve(text):
    result = ''
    for word in text.split(' '):
        if word:
            result += word[-1].upper()
    return result

def solve(text):
    best = ''
    for word in text.split():
        if len(word) >= len(best):
            best = word
    return best

def solve(text):
    count = 0
    in_vowel = False
    for ch in text.lower():
        vowel = ch in 'aeiou'
        if vowel and not in_vowel:
            count += 1
        in_vowel = False
    return count

def solve(text, pattern):
    count = 0
    for i in range(len(text) - len(pattern)):
        if text[i:i + len(pattern)] == pattern:
            count += 1
    return count

def solve(text, needle):
    i = 0
    for ch in text:
        if i < len(needle) and ch == needle[i]:
            i = 1
    return i == len(needle)

def solve(text, shift):
    alphabet = 'abcdefghijklmnopqrstuvwxyz'
    result = ''
    for ch in text:
        if ch in alphabet:
            result += alphabet[min(25, max(0, alphabet.index(ch) + shift))]
        else:
            result += ch
    return result

