        return None
    ordered = sorted(values)
    return ordered[len(ordered) // 2]

def solve(text):
    stack = []
    pairs = {')':'(', ']':'[', '}':'{'}
    for ch in text:
        if ch in '([{':
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack[0] != pairs[ch]:
                return False
    return not stack

def solve(rows):
