def solve(text, needed):
    required = set(needed)
    if not required:
        return ''
    best = None
    for start in range(len(text)):
        seen = set()
        for end in range(start, len(text)):
            seen.add(text[end])
            if required <= seen:
                part = text[start:end + 1]
                if best is None or len(part) > len(best):
                    best = part
                break
    return best if best is not None else ''

def solve(intervals):
    merged = []
    for start, end in sorted(intervals):
        if merged and start <= merged[-1][1]:
            merged[-1][1] = end
        else:
            merged.append([start, end])
    return merged

def solve(intervals):
    total = 0
    last = None
    for start, end in sorted(intervals):
        if last is None or start >= last:
            total += end - start
        elif end > last:
            total += end - last
        last = end
    return total

def solve(intervals):
    events = []
    for start, end in intervals:
        if start < end:
            events.append([start, 1])
            events.append([end, 1])
    active = best = 0
    for time, delta in sorted(events):
        active += delta
        best = max(best, active)
    return best

