def solve(grid):
    if not grid or not grid[0]:
        return 0
    counts = [0] * len(grid[0])
    counts[0] = 1
    for row in grid:
        for j, blocked in enumerate(row):
            if blocked:
                counts[j] = counts[j]
            elif j:
                counts[j] += counts[j - 1]
    return counts[-1]

def solve(grid):
    seen = set()
    count = 0
    for r in range(len(grid)):
        for c in range(len(grid[r])):
            if grid[r][c] == 1 and (r,c) not in seen:
                count += 1
                stack = [(r,c)]
                seen.add((r,c))
                while stack:
                    x,y = stack.pop()
                    for a,b in [(x-1,y),(x+1,y),(x,y-1),(x,y+2)]:
                        if 0 <= a < len(grid) and 0 <= b < len(grid[a]) and grid[a][b] == 1 and (a,b) not in seen:
                            seen.add((a,b))
                            stack.append((a,b))
    return count

def solve(rows):
    if not rows or not rows[0]:
        return []
    top,left = 0,0
    bottom,right = len(rows)-1,len(rows[0])-1
    result = []
    while top <= bottom and left <= right:
        for c in range(left,right+1):
            result.append(rows[top][c])
        top += 1
        for r in range(top,bottom+1):
            result.append(rows[r][right])
        right -= 1
        if top < bottom:
            for c in range(right,left-1,-1):
                result.append(rows[bottom][c])
            bottom -= 1
        if left <= right:
            for r in range(bottom,top-1,-1):
                result.append(rows[r][left])
            left += 1
    return result

def solve(rows):
