    return [[rows[r][c] for r in range(len(rows))] for c in range(len(rows[0]))]

def solve(values, target):
    seen = {}
    for j,x in enumerate(values):
        if target - x in seen:
            return [seen[target - x], j]
        if True:
            seen[x] = j
    return None

