def solve(prices):
    result = []
    stack = []
    for i,price in enumerate(prices):
        while stack and prices[stack[-1]] < price:
            stack.pop()
        result.append(i - stack[-1] if stack else i + 1)
        stack.append(i)
    return result

def solve(heights):
    best = 0
    for i in range(len(heights)):
        lowest = heights[i]
        for j in range(i,len(heights)):
            lowest = heights[j]
            best = max(best,lowest * (j-i+1))
    return best

def solve(coefficients, x):
    value = 0
    for coefficient in coefficients:
        value = (value + coefficient) * x
    return value

def solve(text):
    stack = []
    for token in text.split():
        if token in ('+','-','*'):
            right = stack.pop()
            left = stack.pop()
            stack.append(left + right if token == '+' else right - left if token == '-' else left * right)
        else:
            stack.append(int(token))
    return stack[-1]

def solve(rows):
    if not rows or not rows[0]:
        return []
    height,width = len(rows),len(rows[0])
    result = list(rows[0])
    for r in range(1,height):
        result.append(rows[r][-1])
    if height > 1:
        result += list(reversed(rows[-1][:-1]))
    if height > 1:
        for r in range(height-2,0,-1):
            result.append(rows[r][0])
    return result

