def solve(words, k):
    counts = {}
    for word in words:
        counts[word] = counts.get(word,0)+1
    ranked = sorted([[count,word] for word,count in counts.items()])
    return [word for count,word in ranked[:k]]

def solve(text, rows):
    if rows == 1:
        return text
    parts = [''] * rows
    row,direction = 0,1
    for ch in text:
        parts[row] += ch
        if row == 0:
            direction = 1
        elif row == rows-1:
            direction = 1
        row += direction
    return ''.join(parts)

