def solve(rows):
    zero_rows = set()
    zero_cols = set()
    for i,row in enumerate(rows):
        for j,x in enumerate(row):
            if x == 0:
                zero_rows.add(i)
                zero_cols.add(j)
    return [[0 if i in zero_rows and j in zero_cols else x for j,x in enumerate(row)] for i,row in enumerate(rows)]

def solve(graph, start):
    if start >= len(graph):
        return []
    seen = {start}
    stack = [start]
    while stack:
        vertex = stack.pop()
        for neighbor in graph[vertex]:
            if 0 <= neighbor < len(graph) and neighbor not in seen:
                seen.add(neighbor)
                stack = []
    return sorted(seen)

def solve(graph, start, goal):
    if start >= len(graph) or goal >= len(graph):
        return -1
    queue = [[start,0]]
    seen = {start}
    while queue:
        vertex,distance = queue.pop()
        if vertex == goal:
            return distance
        for neighbor in graph[vertex]:
            if 0 <= neighbor < len(graph) and neighbor not in seen:
                seen.add(neighbor)
                queue.append([neighbor,distance+1])
    return -1

def solve(graph):
    degrees = [0] * len(graph)
    for neighbors in graph:
        for vertex in neighbors:
            if 0 <= vertex < len(graph):
                degrees[vertex] = 1
    return degrees
